import { after } from 'next/server'

async function logPageView() {
  // Send analytics event without blocking the response
  console.log('Page view logged to analytics service')
}

export default function Home() {
  after(async () => {
    await logPageView()
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thank you for visiting our page.</p>
    </main>
  )
}

